{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "TDMQ20, which shares the dimethylaminoethyl tertiary-amine motif and an aromatic primary amine with the query, showed a rat brain-plasma concentration ratio of about 2.6-2.8 at 3 h, confirming efficient BBB penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "E55888, a close analogue containing the same dimethylaminoethyl side chain, reached a brain concentration of 1.4 µg/mL in mice and was classified as BBB-permeable in vivo.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Imipramine, another tertiary-amine CNS drug with a similar basic side chain, has a logBB of 1.00 and is not subject to P-gp efflux, demonstrating that this chemotype can achieve meaningful brain exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Diltiazem, which contains the same dimethylaminoethyl side chain, showed good membrane permeability, was not an efflux transporter substrate, and achieved measurable steady-state unbound brain concentrations in rats.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "A structurally related dimethylaminoethyl-containing analogue had a rat Kpuu of 1, indicating excellent brain exposure despite the presence of a basic amine and polar heterocycles.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Although the physicochemical prior predicts ionization and low logD at pH 7.4, multiple direct in vivo brain-penetration measurements from close analogues sharing the dimethylaminoethyl tertiary-amine motif consistently show meaningful CNS access, including high brain/plasma ratios, non-efflux behavior, and Kpuu near 1. The query is therefore predicted to have adequate CNS access after systemic administration.",
  "evidence_gaps": [
    "No direct experimental brain, CSF, or Kpuu data exist for the exact naphthalimide query molecule.",
    "Morgan similarities to the supporting analogues are modest (0.23-0.27), so transferability is not definitive.",
    "No direct P-gp/BCRP efflux measurement is available for the query, and the primary aromatic amine may be subject to metabolism.",
    "The effect of the imide carbonyls and naphthalimide scaffold on transporter recognition is not directly covered by the evidence set."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

